    const idx=st?LIFECYCLE_STAGES.indexOf(st):-1;
    const next=idx>=0 && idx<LIFECYCLE_STAGES.length-1?LIFECYCLE_STAGES[idx+1]:null;
    const canWrite=!!incidents.access.can_write;
